def length_of_longest_substring(s):
    last_seen = {}
    best = 0
    start = 0
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        best = max(best, i - start + 1)
    return best

bruteForceCode:
def length_of_longest_substring(s):
    best = 0
    n = len(s)
    for start in range(n):
        seen = set()
        for i in range(start, n):
            if s[i] in seen:
                break
            seen.add(s[i])
            best = max(best, i - start + 1)
    return best
